def generate(seed):
    r = random.Random(seed)
    for _ in range(400):
        W = r.randint(9, 16)
        base = [r.choice("##oo...") for _ in range(W)]
        if sum(ch != "." for ch in base) < 4:
            continue
        rows = [base]
        for _ in range(r.randint(2, 4)):
            prev = rows[-1]
            opts = []
            for j in range(W):
                k = sum(prev[x] != "." for x in (j - 1, j, j + 1) if 0 <= x < W)
                if k == 2:
                    opts.append((j, "#"))
                elif k == 1:
                    opts.append((j, "o"))
            if not opts:
                break
            r.shuffle(opts)
            nxt = ["."] * W
            for j, ch in opts[:r.randint(1, len(opts))]:
                nxt[j] = ch
            rows.append(nxt)
        n = sum(row.count("#") for row in rows)
        if n - base.count("#") < 3 or n > 30:
            continue
        return "".join(base) + "|" + str(n)
    return "..#o#..|3"

