def solve(clue):
    """Build any picture over the given footprint holding exactly n stones.

    Each row above is completely determined (as a set of legal positions) by the row
    directly below it: a cell may hold '#' where exactly two of the three cells below are
    occupied, 'o' where exactly one is.  So we just walk upwards, laying stones until the
    quota is met and scattering wood for scaffolding and camouflage.  Randomised by the
    clue so demos of the same clue look the same but different clues look different.
    """
    f, ns = clue.split("|")
    n = int(ns); W = len(f); need = n - f.count("#")
    r = random.Random(clue)

    def legal(prev):
        A = []; B = []
        for j in range(W):
            k = sum(prev[x] != "." for x in (j - 1, j, j + 1) if 0 <= x < W)
            if k == 2:
                A.append(j)
            elif k == 1:
                B.append(j)
        return A, B

    for _ in range(600):
        rows = [list(f)]
        rem = need
        for _ in range(8):
            if rem == 0:
                break
            A, B = legal(rows[-1])
            if not A and not B:
                break
            r.shuffle(A); r.shuffle(B)
            nxt = ["."] * W
            if A:
                hi = min(len(A), rem)
                take = hi if (len(A) >= rem or r.random() < .5) else r.randint(1, hi)
                for j in A[:take]:
                    nxt[j] = "#"
                rem -= take
            if B and (not A or r.random() < .7):
                for j in B[:r.randint(1, len(B))]:
                    nxt[j] = "o"
            if all(ch == "." for ch in nxt):
                break
            rows.append(nxt)
        if rem:
            continue
        for _ in range(r.randint(0, 2)):          # wood-only attic: never changes the count
            B = legal(rows[-1])[1]
            if not B:
                break
            r.shuffle(B)
            nxt = ["."] * W
            for j in B[:r.randint(1, len(B))]:
                nxt[j] = "o"
            rows.append(nxt)
        return "\n".join("".join(x) for x in rows[::-1])
    return ""

